DROP TABLE IF EXISTS `mes_pro_process_pool_submission_review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mes_pro_process_pool_submission_review` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `event_id` bigint NOT NULL COMMENT '工序池提交事件ID',
  `leader_user_id` bigint NOT NULL COMMENT '复核班组长用户ID',
  `review_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '复核状态',
  `review_remark` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复核说明',
  `reviewed_at` datetime NOT NULL COMMENT '服务端复核时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_mes_pp_review_event` (`tenant_id`,`event_id`),
  KEY `idx_mes_pp_review_leader` (`tenant_id`,`leader_user_id`,`reviewed_at`),
  KEY `idx_mes_pp_review_latest_event` (`tenant_id`,`deleted`,`event_id`,`reviewed_at`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MES 工序池班组长提交复核';
/*!40101 SET character_set_client = @saved_cs_client */;

